/**
 * One brand identity, asserted rather than assumed.
 *
 * The failure this file exists for is quiet: the tab icon, the sidebar tile and the install icon are
 * three different files in three different places, so replacing "the logo" can update one and leave
 * the others showing the previous mark for months. Everything here is checked against the SHIPPED
 * files — real PNG bytes, the real manifest, the real shell — not against a name that merely sounds
 * right. The icons are generated by `scripts/brand-icons.cjs`; these tests are what make that the
 * only source, and they fail if a hand-exported bitmap creeps back in.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const exists = (rel) => fs.existsSync(path.join(ROOT, rel));

/** Decode one of our own PNGs (8-bit RGBA, filter 0 only — that is what the generator writes). */
function decodePNG(rel) {
  const buf = fs.readFileSync(path.join(ROOT, rel));
  assert.deepEqual([...buf.subarray(0, 8)], [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a], `${rel} is not a PNG`);
  let offset = 8;
  let header = null;
  const idat = [];
  while (offset < buf.length) {
    const length = buf.readUInt32BE(offset);
    const type = buf.toString('ascii', offset + 4, offset + 8);
    const data = buf.subarray(offset + 8, offset + 8 + length);
    if (type === 'IHDR') {
      header = { width: data.readUInt32BE(0), height: data.readUInt32BE(4), depth: data[8], colorType: data[9] };
    }
    if (type === 'IDAT') idat.push(data);
    offset += 12 + length;
  }
  assert.ok(header, `${rel} has no IHDR`);
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const stride = header.width * 4;
  const pixels = Buffer.alloc(header.width * header.height * 4);
  for (let y = 0; y < header.height; y += 1) {
    const filter = raw[y * (stride + 1)];
    assert.equal(filter, 0, `${rel} row ${y} uses PNG filter ${filter}; the decoder here only knows 0`);
    raw.copy(pixels, y * stride, y * (stride + 1) + 1, y * (stride + 1) + 1 + stride);
  }
  const at = (x, y) => {
    const i = (y * header.width + x) * 4;
    return [pixels[i], pixels[i + 1], pixels[i + 2], pixels[i + 3]];
  };
  return { ...header, at };
}

test('brand: one generator owns the mark, and every size it promises exists', () => {
  const pkg = JSON.parse(read('package.json'));
  assert.equal(pkg.scripts['brand:write'], 'node scripts/brand-icons.cjs', 'the generator must stay runnable');

  const script = read('scripts/brand-icons.cjs');
  const declared = [...script.matchAll(/file: 'icon-(\d+)\.png'/g)].map((m) => Number(m[1]));
  for (const size of [16, 32, 48, 96, 192, 512]) {
    assert.ok(declared.includes(size), `the generator must list the ${size}px icon`);
  }

  for (const rel of [
    'public/brand/icon-16.png', 'public/brand/icon-32.png', 'public/brand/icon-48.png',
    'public/brand/icon-96.png', 'public/brand/icon-192.png', 'public/brand/icon-512.png',
    'public/brand/maskable-512.png', 'public/brand/apple-touch-icon-180.png',
    'public/brand/brocode-mark.svg', 'public/favicon.ico',
  ]) {
    assert.ok(exists(rel), `${rel} is missing — run \`npm run brand:write\``);
  }
  // A generated artifact nobody can regenerate is how the old hand-made bitmaps started.
  assert.match(read('scripts/brand-icons.cjs'), /if \(require\.main === module\) run\(\)/);
});

test('brand: every raster icon is the exact size its filename claims', () => {
  const expected = {
    'public/brand/icon-16.png': 16,
    'public/brand/icon-32.png': 32,
    'public/brand/icon-48.png': 48,
    'public/brand/icon-96.png': 96,
    'public/brand/icon-192.png': 192,
    'public/brand/icon-512.png': 512,
    'public/brand/maskable-512.png': 512,
    'public/brand/apple-touch-icon-180.png': 180,
  };
  for (const [rel, size] of Object.entries(expected)) {
    const png = decodePNG(rel);
    assert.equal(png.depth, 8, `${rel} must be 8-bit`);
    assert.equal(png.colorType, 6, `${rel} must carry an alpha channel`);
    assert.deepEqual([png.width, png.height], [size, size], `${rel} is ${png.width}×${png.height}`);
  }
});

test('brand: the favicon sizes stay transparent, installed sizes stay opaque', () => {
  // "Transparent background where supported": the tab icon sits on the browser's own chrome, so the
  // field outside the rounded tile must be empty — a white plate there is what a bad export looks like.
  for (const rel of ['public/brand/icon-16.png', 'public/brand/icon-32.png', 'public/brand/icon-192.png']) {
    const png = decodePNG(rel);
    assert.equal(png.at(0, 0)[3], 0, `${rel} must be transparent in the corner`);
  }
  // An installed app paints its own plate behind the icon, and iOS rounds the corners itself, so the
  // maskable and apple-touch tiles are full-bleed instead of transparent.
  for (const rel of ['public/brand/maskable-512.png', 'public/brand/apple-touch-icon-180.png']) {
    const png = decodePNG(rel);
    assert.equal(png.at(0, 0)[3], 255, `${rel} must be opaque (no transparent plate)`);
  }
});

test('brand: the mark is centred and square inside its tile, never stretched', () => {
  const png = decodePNG('public/brand/icon-512.png');
  let minX = png.width;
  let maxX = -1;
  let minY = png.height;
  let maxY = -1;
  for (let y = 0; y < png.height; y += 1) {
    for (let x = 0; x < png.width; x += 1) {
      if (png.at(x, y)[3] < 8) continue;
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  const width = maxX - minX + 1;
  const height = maxY - minY + 1;
  assert.ok(Math.abs(width - height) <= 2, `the tile is ${width}×${height} — the mark is distorted`);
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  assert.ok(Math.abs(cx - png.width / 2) <= 2 && Math.abs(cy - png.height / 2) <= 2, 'the mark must be centred');
  // The safe-area padding the maskable variant exists for: at least 10% of the plate on each side.
  const maskable = decodePNG('public/brand/maskable-512.png');
  assert.equal(maskable.at(2, 2)[3], 255, 'the maskable plate must reach the edge');
  const inset = Math.round(maskable.width * 0.08);
  assert.notDeepEqual(
    [maskable.at(inset, maskable.height / 2)[0], maskable.at(inset, maskable.height / 2)[1], maskable.at(inset, maskable.height / 2)[2]],
    [0, 0, 0],
    'the maskable plate is a flat plate, not a black band',
  );
});

test('brand: the 16px favicon still shows the mark, not a colour blob', () => {
  // A favicon that is "the right file" but unreadable at 16 px fails the actual requirement. Two
  // measurable signs that the glyph survived: a bright stroke pixel and the near-black inner tile —
  // the mark's two highest-contrast regions, counted on the real bytes.
  const png = decodePNG('public/brand/icon-16.png');
  let bright = 0;
  let dark = 0;
  for (let y = 0; y < 16; y += 1) {
    for (let x = 0; x < 16; x += 1) {
      const [r, g, b, a] = png.at(x, y);
      if (a < 128) continue;
      if (r > 190 && g > 190 && b > 190) bright += 1;
      if (r < 70 && g < 70 && b < 95) dark += 1;
    }
  }
  assert.ok(dark >= 6, `the inner tile covers only ${dark} opaque pixels at 16px`);
  assert.ok(bright >= 3, `the code glyph covers only ${bright} bright pixels at 16px`);
  // The small variant exists because three glyphs merge: at 16 px the slash is deliberately gone.
  const generator = read('scripts/brand-icons.cjs');
  assert.match(generator, /MARK_SMALL/, '16–32 px must use the opticall- tuned variant');
});

test('brand: the shell names the tab icon, the iOS tile and the vector master', () => {
  const html = read('index.html');
  assert.match(html, /<link rel="icon" href="\.\/favicon\.ico" sizes="16x16 32x32 48x48" \/>/);
  assert.match(html, /<link rel="icon" type="image\/png" sizes="32x32" href="\.\/brand\/icon-32\.png" \/>/);
  assert.match(html, /rel="apple-touch-icon" sizes="180x180" href="\.\/brand\/apple-touch-icon-180\.png"/);
  assert.match(html, /type="image\/svg\+xml" href="\.\/brand\/brocode-mark\.svg"/);
  assert.match(html, /"logo": "https:\/\/[^"]*\/brand\/icon-512\.png"/, 'the JSON-LD organisation logo is the new mark');
});

test('brand: the PWA manifest installs the new icon on every platform', () => {
  const manifest = JSON.parse(read('public/manifest.webmanifest'));
  assert.equal(manifest.name, 'BroCode');
  const byPurpose = (purpose) => manifest.icons.filter((i) => i.purpose === purpose);
  const any = byPurpose('any');
  const maskable = byPurpose('maskable');
  assert.deepEqual(any.map((i) => i.sizes).sort(), ['192x192', '512x512'], 'install needs 192 and 512');
  assert.deepEqual(maskable.map((i) => i.sizes), ['512x512'], 'Android needs one maskable 512');
  for (const icon of manifest.icons) {
    const rel = `public/${icon.src.replace(/^\.\//, '')}`;
    assert.ok(exists(rel), `manifest promises ${icon.src}, which does not ship`);
    assert.equal(icon.type, 'image/png');
  }
});

test('brand: every surface draws the same component, and the old bitmaps are gone', () => {
  const app = read('src/app/App.tsx');
  assert.match(app, /import \{ BrandMark \} from '\.\.\/components\/shared\/BrandMark'/);
  // The empty alt while the wordmark is visible, the brand name when the rail collapses (the tile is
  // then the only thing naming the app).
  assert.match(app, /<BrandMark size=\{44\} alt=\{collapsed \? 'BroCode' : ''\} \/>/);
  assert.match(read('src/components/ui/ErrorBoundary.tsx'), /<BrandMark size=\{20\} alt="" \/>/);

  const mark = read('src/components/shared/BrandMark.tsx');
  assert.match(mark, /'\.\/brand\/brocode-mark\.svg'/);
  assert.match(mark, /'\.\/brand\/icon-192\.png'/, 'the SVG needs a PNG fallback');
  assert.match(mark, /onError=/, 'a refused SVG must not leave a broken-image glyph');

  for (const rel of ['public/brocode.png', 'public/brocode-192.png', 'public/brocode-256.png']) {
    assert.equal(exists(rel), false, `${rel} is the old logo and must not ship`);
  }
  // No source or shell file may still point at the old filenames.
  const offenders = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(path.join(ROOT, dir), { withFileTypes: true })) {
      const rel = `${dir}/${entry.name}`;
      if (entry.isDirectory()) walk(rel);
      else if (/\.(tsx?|cjs|mjs|html|webmanifest|json|md)$/.test(entry.name)) offenders.push(rel);
    }
  };
  walk('src');
  offenders.push('index.html', 'public/manifest.webmanifest', 'README.md', 'scripts/og.cjs', 'scripts/brand-icons.cjs');
  // Comments may explain what replaced what (the generator's own header does), so only live code
  // counts: a filename that survives in a comment is documentation, not a reference.
  const stale = offenders.filter((rel) =>
    /brocode(?:-192|-256)?\.png/.test(read(rel).replace(/\/\*[\s\S]*?\*\//g, '').replace(/<!--[\s\S]*?-->/g, '')),
  );
  assert.deepEqual(stale, [], `old logo references:\\n${stale.join('\\n')}`);
});

test('brand: the service worker purges the cached old logo', () => {
  const sw = read('public/sw.js');
  const version = /const CACHE = 'aiml-v(\d+)'/.exec(sw);
  assert.ok(version, 'the cache name must stay versioned');
  assert.ok(Number(version[1]) >= 9, 'a new icon path needs a cache bump or installs keep the old mark');
  assert.match(sw, /\(png\|svg\|ico\)\$\/i\.test\(url\.pathname\)/, 'brand bitmaps must be cached by the asset rule');
});
